1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	
34	// The catalogue of insurable item types. Each type carries both figures the
35	// office needs: what it costs to insure (base premium) and what it is worth
36	// when destroyed (insurance value). Keeping them in one row means a new item
37	// type is one edit, and the two figures can never drift apart.
38	const CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
39	  sword: { basePremium: 100, insuranceValue: 1000 },
40	  amulet: { basePremium: 60, insuranceValue: 600 },
41	  staff: { basePremium: 80, insuranceValue: 800 },
42	  potion: { basePremium: 40, insuranceValue: 400 },
43	  rune: { basePremium: 25, insuranceValue: 250 },
44	  moonstone: { basePremium: 25, insuranceValue: 250 },
45	};
46	
47	// Three of this file's lookups can miss, and in every case a miss is the office
48	// declining rather than a bug: an uninsurable type, an uncovered item, an absent
49	// policy. Each caller names its own offender; this says once what they share — a
50	// miss is a domain error naming what was declined, never an undefined that
51	// travels on to surface later as a TypeError.
52	const foundOrThrow = <Found,>(found: Found | undefined, declined: string): Found => {
53	  if (found === undefined) {
54	    throw new Error(declined);
55	  }
56	  return found;
57	};
58	
59	// Both catalogue figures are read through this one row lookup, so an item's type
60	// is resolved against the catalogue in exactly one place — which makes it also
61	// the one place that can tell an insurable type from an uninsurable one. The
62	// catalogue does not merely price the types the MHPCO insures; it DEFINES them,
63	// so a missing row is not a lookup miss to defend against but the office
64	// declining the item, and it is reported in those terms.
65	const catalogueEntryFor = (item: Item) =>
66	  foundOrThrow(
67	    CATALOGUE[item.type],
68	    `the MHPCO does not insure items of type "${item.type}"`,
69	  );
70	
71	// Totalling a catalogue column over a list of items is the same operation on the
72	// premium side and the claim side; only the column differs. Naming it once keeps
73	// the two columns visibly separate — which is the point: the building-block
74	// discount rewrites the basePremium column and never touches insuranceValue.
75	const totalOfColumn =
76	  (columnOf: (item: Item) => number) =>
77	  (items: Item[]): number =>
78	    items.reduce((total, item) => total + columnOf(item), 0);
79	
80	const basePremiumOf = (item: Item): number => catalogueEntryFor(item).basePremium;
81	
82	const BLOCK_SIZE = 3;
83	const BLOCK_BASE_PREMIUM = 60;
84	
85	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
86	  alikeItems.length === BLOCK_SIZE;
87	
88	const sumOfBasePremiums = totalOfColumn(basePremiumOf);
89	
90	const CURSE_SURCHARGE_RATE = 0.5;
91	const HIGH_ENCHANTMENT_LEVEL = 5;
92	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
93	
94	const isCursed = (item: Item): boolean => item.cursed === true;
95	
96	// An unenchanted item is enchantment 0, so every threshold reads the level the
97	// same way. The MHPCO sets several enchantment thresholds for different rules;
98	// each names its own level and compares through here.
99	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
100	
101	const carriesEnchantmentSurcharge = (item: Item): boolean =>
102	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
103	
104	// A rate table prices one subject: every row whose risk applies contributes its
105	// rate, and the total is their sum. Both the item surcharges and the policy-wide
106	// modifiers are rate tables — they differ only in what they are applied to.
107	type RateTable<Subject> = { appliesTo: (subject: Subject) => boolean; rate: number }[];
108	
109	const totalRateFrom = <Subject,>(table: RateTable<Subject>, subject: Subject): number =>
110	  table.reduce((total, row) => (row.appliesTo(subject) ? total + row.rate : total), 0);
111	
112	// Every item-specific surcharge is a rate on THAT item's base premium, charged
113	// when its risk applies. Adding a new one means adding a row here — nothing else.
114	const ITEM_SURCHARGES: RateTable<Item> = [
115	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
116	  { appliesTo: carriesEnchantmentSurcharge, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
117	];
118	
119	const surchargeRateOn = (item: Item): number => totalRateFrom(ITEM_SURCHARGES, item);
120	
121	const itemSurchargesOn = (items: Item[]): number =>
122	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
123	
124	// Items of the same type are "alike"; each group is priced together so a
125	// building block can be recognised.
126	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
127	  ...items
128	    .reduce(
129	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
130	      new Map<string, Item[]>(),
131	    )
132	    .values(),
133	];
134	
135	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
136	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
137	
138	const policyBaseOf = (items: Item[]): number =>
139	  alikeItemGroupsIn(items).reduce(
140	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
141	    0,
142	  );
143	
144	// Rounding always favours the MHPCO. Which direction that is follows from which
145	// way the money moves: an amount the office RECEIVES is rounded up, an amount it
146	// PAYS is rounded down. Naming the two directions makes the rule one concept
147	// rather than two opposite-looking halves, and each call site says which kind of
148	// amount it holds — so the reason for the direction is in the code, not a comment.
149	const settledAsReceived = Math.ceil;
150	const settledAsPaid = Math.floor;
151	
152	const LOYALTY_YEARS = 2;
153	const LOYALTY_DISCOUNT_RATE = -0.2;
154	
155	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
156	
157	// A quote insures items the policy did not previously cover, so every quote is
158	// a first insurance OF THOSE ITEMS — including a follow-up contract, which is a
159	// later contract for the same customer but still the first for its own items.
160	// That is why this holds for every quote and reads as a condition that is always
161	// met, rather than as a rule with no condition at all.
162	const insuresItemsForTheFirstTime = (): boolean => true;
163	
164	const isLongStanding = ({ customer }: QuoteContext): boolean =>
165	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
166	
167	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
168	  precedingQuotes > 0;
169	
170	// A quote is priced from the customer plus its place in the scenario's history.
171	type QuoteContext = { customer: Customer; precedingQuotes: number };
172	
173	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
174	// base that already includes the item surcharges. Surcharges carry a positive
175	// rate, discounts a negative one. Adding a new one means adding a row here.
176	const POLICY_MODIFIERS: RateTable<QuoteContext> = [
177	  { appliesTo: insuresItemsForTheFirstTime, rate: FIRST_INSURANCE_SURCHARGE_RATE },
178	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
179	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
180	];
181	
182	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
183	  policyBase * totalRateFrom(POLICY_MODIFIERS, context);
184	
185	const quoteFor = (items: Item[], context: QuoteContext): Result => {
186	  const policyBase = policyBaseOf(items);
187	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
188	  return {
189	    premium: settledAsReceived(
190	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
191	    ),
192	  };
193	};
194	
195	const DEDUCTIBLE_PER_DAMAGE = 100;
196	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
197	
198	const insuranceValueOf = (item: Item): number => catalogueEntryFor(item).insuranceValue;
199	
200	// The insurance sum totals the value column over every insured item — one item,
201	// one row, no grouping. Blocks are a premium concept and cannot reach it.
202	const insuranceSumOf = totalOfColumn(insuranceValueOf);
203	
204	// A policy created by a quote step, tracked by that step's index so later claims
205	// can find it and draw down its cap.
206	type Policy = { items: Item[]; remainingCap: number };
207	
208	const policyFor = (items: Item[]): Policy => ({
209	  items,
210	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
211	});
212	
213	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
214	const HALF_REIMBURSEMENT_RATE = 0.5;
215	const FULL_REIMBURSEMENT_RATE = 1;
216	
217	// A distinct rule from the premium's HIGH_ENCHANTMENT_LEVEL, at a distinct
218	// level: this one halves what a claim pays out, that one raises what a policy
219	// costs. They move independently — deliberately not shared.
220	const reimbursesOnlyHalf = (item: Item): boolean =>
221	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
222	
223	// How much of the damage the MHPCO reimburses, before the deductible bites.
224	const reimbursementRateFor = (item: Item): number =>
225	  reimbursesOnlyHalf(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
226	
227	// A damage names only an item TYPE, so it can identify no more than the type of
228	// the item it refers to — which is why this takes the type alone: the amount has
229	// no say in WHICH item answers for the damage. It returns the first insured item
230	// of that type as the representative whose traits price the damage.
231	//
232	// It is also the claim side's coverage guard. A type absent from the policy and
233	// a type the MHPCO does not insure at all are indistinguishable here, and both
234	// are declined by this one lookup: an uninsurable type could never have been
235	// quoted, so it can never appear among a policy's items.
236	//
237	// UNTESTED ASSUMPTION: that the first match is the right representative. Where a
238	// policy holds several alike items, the suite never distinguishes them — its only
239	// two-alike-items example insures two IDENTICAL swords, so first-match is
240	// unobservable there, and the spec offers no example pairing one type with
241	// DIFFERING enchantment or material. So this is an assumption the tests permit,
242	// not one they confirm. Should such an example appear, the damage would have to
243	// be matched to a specific item and this would be the place that changes.
244	const insuredItemOfType = (policy: Policy, itemType: string): Item =>
245	  foundOrThrow(
246	    policy.items.find((item) => item.type === itemType),
247	    `the policy does not cover an item of type "${itemType}"`,
248	  );
249	
250	// A damage is what the incident cost; an office cannot be owed money by a
251	// misfortune, so a negative amount is a malformed claim rather than a refund.
252	const damagedAmountOf = (damage: Damage): number => {
253	  if (damage.amount < 0) {
254	    throw new Error(`a damage cannot be negative, but was ${damage.amount}`);
255	  }
256	  return damage.amount;
257	};
258	
259	const reimbursedAmountFor = (damage: Damage, policy: Policy): number =>
260	  damagedAmountOf(damage) *
261	  reimbursementRateFor(insuredItemOfType(policy, damage.itemType));
262	
263	// The deductible bites once per damage, after the reimbursement rate is applied
264	// — never the other way round, which would pay out more.
265	const payoutForDamage = (damage: Damage, policy: Policy): number =>
266	  reimbursedAmountFor(damage, policy) - DEDUCTIBLE_PER_DAMAGE;
267	
268	// How many times each type appears among a list of things that name a type.
269	// Items and damages name theirs under different keys, so each caller says how
270	// its own kind is read rather than first flattening to a list of bare strings.
271	// The file's other by-type reading, alikeItemGroupsIn, collects the items
272	// themselves because the premium side prices them; here only the tally matters.
273	const countByType = <Named,>(
274	  named: Named[],
275	  typeOf: (one: Named) => string,
276	): Map<string, number> =>
277	  named.reduce((counts, one) => {
278	    const type = typeOf(one);
279	    return counts.set(type, (counts.get(type) ?? 0) + 1);
280	  }, new Map<string, number>());
281	
282	// A damage entry stands for one damaged item, so an incident cannot name more
283	// damages of a type than the policy insures of that type. Asking for the
284	// overclaimed type — rather than testing each damage in turn — puts this beside
285	// the file's other three misses: a lookup that yields nothing when all is well
286	// and names the offender when it is not.
287	const overclaimedTypeIn = (incident: Incident, policy: Policy): string | undefined => {
288	  const insuredCounts = countByType(policy.items, (item) => item.type);
289	  return [...countByType(incident.damages, (damage) => damage.itemType)]
290	    .filter(([type, damaged]) => damaged > (insuredCounts.get(type) ?? 0))
291	    .map(([type]) => type)
292	    .at(0);
293	};
294	
295	// The whole claim is rejected rather than settled in part, so the overclaim is
296	// checked before any damage is priced.
297	const rejectOverclaimedTypes = (incident: Incident, policy: Policy): void => {
298	  const overclaimed = overclaimedTypeIn(incident, policy);
299	  if (overclaimed !== undefined) {
300	    throw new Error(
301	      `the policy does not cover that many items of type "${overclaimed}"`,
302	    );
303	  }
304	};
305	
306	// One incident can damage several items; each damage is settled on its own
307	// (and so bears its own deductible), and the incident pays out their sum.
308	const payoutForIncident = (incident: Incident, policy: Policy): number => {
309	  rejectOverclaimedTypes(incident, policy);
310	  return incident.damages.reduce(
311	    (sum, damage) => sum + payoutForDamage(damage, policy),
312	    0,
313	  );
314	};
315	
316	// A payout is drawn from the policy's cap, leaving less for later claims.
317	const capDrawnDownBy = (policy: Policy, payout: number): Policy => ({
318	  ...policy,
319	  remainingCap: policy.remainingCap - payout,
320	});
321	
322	// The policy pays no more than the cap it has left, however large the damage.
323	const payoutWithinCapOf = (policy: Policy, desiredPayout: number): number =>
324	  Math.min(desiredPayout, policy.remainingCap);
325	
326	// Settling a claim pays out and draws the cap down by the same amount, so the
327	// result the customer sees is the payout plus the cap that payout left behind.
328	const claimFor = (incident: Incident, policy: Policy): [Result, Policy] => {
329	  const payout = settledAsPaid(
330	    payoutWithinCapOf(policy, payoutForIncident(incident, policy)),
331	  );
332	  const settledPolicy = capDrawnDownBy(policy, payout);
333	  return [{ payout, remainingCap: settledPolicy.remainingCap }, settledPolicy];
334	};
335	
336	// What the scenario has accumulated before the current step: the results so far,
337	// the history a quote is priced against, and the policies earlier quotes created.
338	type ScenarioState = {
339	  results: Result[];
340	  precedingQuotes: number;
341	  policies: Record<number, Policy>;
342	};
343	
344	const INITIAL_SCENARIO_STATE: ScenarioState = {
345	  results: [],
346	  precedingQuotes: 0,
347	  policies: {},
348	};
349	
350	// Every step reports exactly one result and leaves one policy at its index —
351	// the two things both step kinds always do. Recording them is named once here
352	// rather than rebuilt in each of them.
353	const withStepRecorded = (
354	  state: ScenarioState,
355	  result: Result,
356	  policyIndex: number,
357	  policy: Policy,
358	): ScenarioState => ({
359	  ...state,
360	  results: [...state.results, result],
361	  policies: { ...state.policies, [policyIndex]: policy },
362	});
363	
364	const afterQuote = (
365	  state: ScenarioState,
366	  items: Item[],
367	  customer: Customer,
368	  stepIndex: number,
369	): ScenarioState => ({
370	  ...withStepRecorded(
371	    state,
372	    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
373	    stepIndex,
374	    policyFor(items),
375	  ),
376	  precedingQuotes: state.precedingQuotes + 1,
377	});
378	
379	// A claim names the quote step whose policy it draws on. Only a quote creates a
380	// policy, so an index no quote reached is the claim naming a policy that does
381	// not exist.
382	const policyAt = (state: ScenarioState, policyIndex: number): Policy =>
383	  foundOrThrow(
384	    state.policies[policyIndex],
385	    `there is no policy at step ${policyIndex}`,
386	  );
387	
388	const afterClaim = (
389	  state: ScenarioState,
390	  policyIndex: number,
391	  incident: Incident,
392	): ScenarioState => {
393	  const [result, settledPolicy] = claimFor(incident, policyAt(state, policyIndex));
394	  return withStepRecorded(state, result, policyIndex, settledPolicy);
395	};
396	
397	const afterStep = (
398	  state: ScenarioState,
399	  step: Step,
400	  customer: Customer,
401	  stepIndex: number,
402	): ScenarioState =>
403	  step.op === "quote"
404	    ? afterQuote(state, step.items, customer, stepIndex)
405	    : afterClaim(state, step.policy, step.incident);
406	
407	export const runScenario = (scenario: Scenario): { results: Result[] } => {
408	  const { results } = scenario.steps.reduce(
409	    (state, step, stepIndex) => afterStep(state, step, scenario.customer, stepIndex),
410	    INITIAL_SCENARIO_STATE,
411	  );
412	  return { results };
413	};
