2	import { runScenario, type Scenario } from "./claim-office.js";
3	
4	// Reading a file descriptor rather than a path is how the office takes a
5	// scenario from a pipe; descriptor 0 is standard input by POSIX convention.
6	const STDIN_FILE_DESCRIPTOR = 0;
7	
8	const REJECTED = 1;
9	
10	// What a caught reason says for itself. An Error explains itself by its
11	// message; anything else thrown has no message to give, so it is stated as it
12	// stands rather than asserted to be an Error and silently printed as
13	// "undefined". The office always has a reason to state.
14	const reasonGivenBy = (declined: unknown): string =>
15	  declined instanceof Error ? declined.message : String(declined);
16	
17	try {
18	  const scenario = JSON.parse(
19	    readFileSync(STDIN_FILE_DESCRIPTOR, "utf8"),
20	  ) as Scenario;
21	  process.stdout.write(JSON.stringify(runScenario(scenario)));
22	} catch (declined) {
23	  // The office states its reason and nothing else: a stack trace is our
24	  // business, not the claimant's.
25	  process.stderr.write(`${reasonGivenBy(declined)}\n`);
26	  process.exit(REJECTED);
27	}
